def min_element_after_digit_sum(nums):
    # Helper to calculate digit sum of a number
    def digit_sum(n):
        total = 0
        while n > 0:
            total += n % 10
            n //= 10
        return total

    min_sum = float('inf')
    for num in nums:
        dsum = digit_sum(num)
        if dsum < min_sum:
            min_sum = dsum
    return min_sum
